fn is_palindrome(text: Vec<char>) -> bool {
    let len = text.len();
    // Compare characters from the front and back moving towards the center
    for i in 0..len / 2 {
        let c1 = text[i].to_ascii_lowercase();
        let c2 = text[len - 1 - i].to_ascii_lowercase();
        if c1 != c2 {
            return false;
        }
    }
    true
}